<?php
require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/permissions.php';require_once __DIR__.'/includes/icons.php';require_once __DIR__.'/includes/novedades_semanales_common.php';
auth_require();permissions_require_menu('novedades_semanales_panel');
$cfg=require __DIR__.'/config.php';date_default_timezone_set($cfg['app']['tz']??'UTC');$APP_USER=auth_user();$APP_ROLE=auth_es_admin()?'Administrador':'Operador';$ACTIVE='novedades_semanales_panel';
$db=clear_db();$ready=ns_module_ready($db);$commentsReady=$ready&&ns_comments_ready($db);$reportReady=$ready&&ns_report_ready($db);$today=new DateTimeImmutable('now');$prefs=ns_preferences();$period=ns_period($_GET,$today,$prefs);
$weeklyType=ns_chart_type($_GET['grafico_evolucion']??($prefs['panel_weekly_chart']??'line'),'line');$typeChartType=ns_chart_type($_GET['grafico_tipo']??($prefs['panel_type_chart']??'bar'),'bar');
$weeklyPalette=(string)($_GET['paleta_evolucion']??($prefs['panel_weekly_palette']??'blues'));if(!in_array($weeklyPalette,['blues','multicolor'],true))$weeklyPalette='blues';$typePalette=(string)($_GET['paleta_tipo']??($prefs['panel_type_palette']??'blues'));if(!in_array($typePalette,['blues','multicolor'],true))$typePalette='blues';
$weeklyRows=[];$typeRows=[];$topRows=[];$currentTotal=0;$previousTotal=0;$updated='';$canUseComments=$commentsReady&&(permissions_can('comments.view')||permissions_can('comments.create'));
if($ready){
  $range=[$period['from_value'],$period['to_value']];
  $weeklyRows=$db->all("SELECT CONVERT(varchar(10),SEMANA_DESDE,23) SEMANA_DESDE,CONVERT(varchar(10),MAX(SEMANA_HASTA),23) SEMANA_HASTA,SUM(TOTAL_ALARMAS) TOTAL FROM dbo.CLEAR_NOVEDADES_SEMANALES_CACHE WHERE SEMANA_DESDE BETWEEN CONVERT(date,?,23) AND CONVERT(date,?,23) GROUP BY SEMANA_DESDE ORDER BY SEMANA_DESDE",$range);
  $currentTotal=(int)$db->scalar("SELECT COALESCE(SUM(TOTAL_ALARMAS),0) FROM dbo.CLEAR_NOVEDADES_SEMANALES_CACHE WHERE SEMANA_DESDE BETWEEN CONVERT(date,?,23) AND CONVERT(date,?,23)",$range);
  $previousTo=$period['from']->modify('-7 days');$previousFrom=$previousTo->modify('-'.(($period['weeks']-1)*7).' days');
  $previousTotal=(int)$db->scalar("SELECT COALESCE(SUM(TOTAL_ALARMAS),0) FROM dbo.CLEAR_NOVEDADES_SEMANALES_CACHE WHERE SEMANA_DESDE BETWEEN CONVERT(date,?,23) AND CONVERT(date,?,23)",[$previousFrom->format('Y-m-d'),$previousTo->format('Y-m-d')]);
  $typeRows=$db->all("SELECT TIPO_INSTALACION,SUM(TOTAL_ALARMAS) TOTAL FROM dbo.CLEAR_NOVEDADES_SEMANALES_CACHE WHERE SEMANA_DESDE BETWEEN CONVERT(date,?,23) AND CONVERT(date,?,23) GROUP BY TIPO_INSTALACION ORDER BY SUM(TOTAL_ALARMAS) DESC",$range);
  $join=$commentsReady?"LEFT JOIN dbo.CLEAR_NOVEDADES_SEMANALES_COMENTARIOS CO ON CO.SEMANA_DESDE=C.SEMANA_DESDE AND CO.TIPO_INSTALACION=C.TIPO_INSTALACION AND CO.INSTALACION=C.INSTALACION AND CO.TAG=C.TAG":"";
  $commentSelect=$commentsReady?",CO.COMENTARIO,CO.ACTIVO COMENTARIO_ACTIVO,CO.USUARIO_CARGA,CO.USUARIO_MODIFICACION":",N'' COMENTARIO,CONVERT(bit,0) COMENTARIO_ACTIVO";
  $topRows=$db->all("SELECT TOP 20 ".ns_cache_select('C')."$commentSelect FROM dbo.CLEAR_NOVEDADES_SEMANALES_CACHE C $join WHERE C.SEMANA_DESDE BETWEEN CONVERT(date,?,23) AND CONVERT(date,?,23) ORDER BY C.TOTAL_ALARMAS DESC,C.INSTALACION,C.TAG",$range);
  $updated=(string)$db->scalar("SELECT CONVERT(varchar(19),MAX(FECHA_ACTUALIZACION),120) FROM dbo.CLEAR_NOVEDADES_SEMANALES_CACHE WHERE SEMANA_DESDE BETWEEN CONVERT(date,?,23) AND CONVERT(date,?,23)",$range);
}
$commented=0;foreach($topRows as $row)if((int)ns_value($row,'COMENTARIO_ACTIVO',0)===1&&trim((string)ns_value($row,'COMENTARIO'))!=='')$commented++;$coverage=count($topRows)?$commented/count($topRows)*100:0;$variation=$previousTotal>0?(($currentTotal-$previousTotal)/$previousTotal*100):0;
$weeklyChart=['labels'=>[],'dates'=>[],'values'=>[],'type'=>$weeklyType,'palette'=>$weeklyPalette];foreach($weeklyRows as $row){$start=ns_parse_date(ns_value($row,'SEMANA_DESDE'));if(!$start)continue;$weeklyChart['labels'][]='Sem. '.$start->modify('+6 days')->format('W');$weeklyChart['dates'][]=$start->format('Y-m-d');$weeklyChart['values'][]=(int)ns_value($row,'TOTAL',0);}
$typeChart=['labels'=>[],'values'=>[],'type'=>$typeChartType,'palette'=>$typePalette];foreach($typeRows as $row){$typeChart['labels'][]=(string)ns_value($row,'TIPO_INSTALACION');$typeChart['values'][]=(int)ns_value($row,'TOTAL',0);}
$weeklyPayload=['kind'=>'chart','chart_type'=>$weeklyType,'palette'=>$weeklyPalette,'labels'=>$weeklyChart['labels'],'datasets'=>[['label'=>'Total de alarmas','values'=>$weeklyChart['values']]]];$typePayload=['kind'=>'chart','chart_type'=>$typeChartType,'palette'=>$typePalette,'labels'=>$typeChart['labels'],'datasets'=>[['label'=>'Alarmas','values'=>$typeChart['values']]]];
?>
