<div class="page__head nsHead"><div><h1 class="page__title">Novedades semanales</h1><div class="page__sub">Módulo independiente de análisis, comparación, seguimiento y armado de reportes.</div></div><div class="page__live"><span class="dot"></span><?php echo $ready?'Caché independiente':'Requiere instalación'; ?></div></div><?php ns_render_module_nav($ACTIVE); ?>
<?php if(!$ready):ns_render_not_installed();else: ?>
