<section class="nsStats"><article class="nsStat"><div class="nsStat__label">Total del período</div><div class="nsStat__value"><?php echo ns_num($currentTotal); ?></div><div class="nsStat__detail"><?php echo h(ns_period_label($period)); ?></div></article><article class="nsStat <?php echo $variation>0?'is-red':'is-green'; ?>"><div class="nsStat__label">Variación contra período anterior</div><div class="nsStat__value"><?php echo ($variation>0?'+':'').ns_percent($variation); ?></div><div class="nsStat__detail"><?php echo $previousTotal?'Anterior: '.ns_num($previousTotal):'Sin base anterior'; ?></div></article><article class="nsStat is-amber"><div class="nsStat__label">Malos actores detectados</div><div class="nsStat__value"><?php echo ns_num(count($topRows)); ?></div><div class="nsStat__detail">Primeros 20 del período.</div></article><article class="nsStat is-green"><div class="nsStat__label">Seguimiento documentado</div><div class="nsStat__value"><?php echo ns_percent($coverage); ?></div><div class="nsStat__detail"><?php echo ns_num($commented); ?> de <?php echo ns_num(count($topRows)); ?> con comentario.</div></article></section>
<section class="nsCards"><article class="nsCard nsCard--wide"><div class="nsCard__head"><div><h2>Evolución semanal</h2><p>Valores visibles; seleccioná un punto para abrir su ranking.</p></div><div class="nsChartControls"><select name="grafico_evolucion" form="nsPanelChartForm" data-ns-chart-type data-ns-preference="panel_weekly_chart"><option value="line" <?php echo $weeklyType==='line'?'selected':''; ?>>Líneas</option><option value="bar" <?php echo $weeklyType==='bar'?'selected':''; ?>>Barras</option><option value="doughnut" <?php echo $weeklyType==='doughnut'?'selected':''; ?>>Dona</option></select><select name="paleta_evolucion" form="nsPanelChartForm" data-ns-chart-palette data-ns-preference="panel_weekly_palette"><option value="blues" <?php echo $weeklyPalette==='blues'?'selected':''; ?>>Azules</option><option value="multicolor" <?php echo $weeklyPalette==='multicolor'?'selected':''; ?>>Multicolor</option></select><?php if($reportReady)echo ns_report_pick(ns_report_key('panel-evolucion',[$period['from_value'],$period['to_value'],$weeklyType,$weeklyPalette]),'chart','Evolución semanal · '.ns_period_label($period),$weeklyPayload); ?></div></div><div class="nsCard__body"><div class="nsChartBox"><canvas id="nsWeeklyChart"></canvas></div></div></article>
<article class="nsCard"><div class="nsCard__head"><div><h2>Accesos del módulo</h2><p>Funciones desacopladas de las alarmas actuales.</p></div></div><div class="nsCard__body nsQuickLinks"><a class="nsQuickLink" href="novedades_semanales_malos_actores.php"><div><b>Malos actores</b><span>Ranking y comentarios por TAG.</span></div><strong>›</strong></a><a class="nsQuickLink" href="novedades_semanales_comparativa.php"><div><b>Comparativa</b><span>Semanas, instalaciones y TAG.</span></div><strong>›</strong></a><a class="nsQuickLink" href="novedades_semanales_seguimiento.php"><div><b>Seguimiento</b><span>Justificados y pendientes.</span></div><strong>›</strong></a><a class="nsQuickLink" href="novedades_semanales_reporte.php"><div><b>Reporte</b><span>Elementos elegidos, PDF, Excel y email.</span></div><strong>›</strong></a></div></article>
<article class="nsCard nsCard--full"><div class="nsCard__head"><div><h2>Distribución por tipo</h2><p>Clasificación operativa del período seleccionado.</p></div><div class="nsChartControls"><select name="grafico_tipo" form="nsPanelChartForm" data-ns-chart-type data-ns-preference="panel_type_chart"><option value="line" <?php echo $typeChartType==='line'?'selected':''; ?>>Líneas</option><option value="bar" <?php echo $typeChartType==='bar'?'selected':''; ?>>Barras</option><option value="doughnut" <?php echo $typeChartType==='doughnut'?'selected':''; ?>>Dona</option></select><select name="paleta_tipo" form="nsPanelChartForm" data-ns-chart-palette data-ns-preference="panel_type_palette"><option value="blues" <?php echo $typePalette==='blues'?'selected':''; ?>>Azules</option><option value="multicolor" <?php echo $typePalette==='multicolor'?'selected':''; ?>>Multicolor</option></select><?php if($reportReady)echo ns_report_pick(ns_report_key('panel-tipos',[$period['from_value'],$period['to_value'],$typeChartType,$typePalette]),'chart','Distribución por tipo · '.ns_period_label($period),$typePayload); ?></div></div><div class="nsCard__body"><div class="nsChartBox"><canvas id="nsTypeChart"></canvas></div></div></article></section>
<form id="nsPanelChartForm" method="get"><input type="hidden" name="desde" value="<?php echo h($period['from_value']); ?>"><input type="hidden" name="hasta" value="<?php echo h($period['to_value']); ?>"></form>
<section class="nsTableCard"><div class="nsTableHead"><div><h2>Principales malos actores</h2><p><?php echo h(ns_period_label($period)); ?> · filtrá y ordená cada columna.</p></div><div class="nsTableMeta">Actualizado: <b><?php echo h($updated?:'sin datos'); ?></b></div></div><div class="tablescroll"><table class="grid nsTable" id="nsPanelTable"><thead><tr><th>REPORTE</th><th><button class="nsClientSort" data-ns-sort-client data-table="nsPanelTable" data-column="1">SEMANA</button></th><th><button class="nsClientSort" data-ns-sort-client data-table="nsPanelTable" data-column="2">TIPO</button></th><th><button class="nsClientSort" data-ns-sort-client data-table="nsPanelTable" data-column="3">INSTALACIÓN</button></th><th><button class="nsClientSort" data-ns-sort-client data-table="nsPanelTable" data-column="4">TAG</button></th><th><button class="nsClientSort" data-ns-sort-client data-table="nsPanelTable" data-column="5">DESCRIPCIÓN</button></th><th><button class="nsClientSort" data-ns-sort-client data-table="nsPanelTable" data-column="6" data-kind="number">TOTAL</button></th><th>CAMPO EXT.</th><th>COMENTARIO</th></tr><tr class="nsFilterRow"><th></th><th><input data-ns-client-filter data-table="nsPanelTable" data-column="1" placeholder="Semana"></th><th><select data-ns-client-filter data-table="nsPanelTable" data-column="2"><option value="">Todos</option><?php foreach(ns_type_options() as $v=>$l): ?><option value="<?php echo h($v); ?>"><?php echo h($l); ?></option><?php endforeach; ?></select></th><th><input data-ns-client-filter data-table="nsPanelTable" data-column="3" placeholder="Buscar"></th><th><input data-ns-client-filter data-table="nsPanelTable" data-column="4" placeholder="Buscar"></th><th><input data-ns-client-filter data-table="nsPanelTable" data-column="5" placeholder="Buscar"></th><th><input data-ns-client-filter data-table="nsPanelTable" data-column="6" placeholder="Buscar"></th><th><input data-ns-client-filter data-table="nsPanelTable" data-column="7" placeholder="Buscar"></th><th><input data-ns-client-filter data-table="nsPanelTable" data-column="8" placeholder="Buscar"></th></tr></thead><tbody><?php if(!$topRows): ?><tr><td colspan="9" class="nsEmpty">No hay datos para el período seleccionado.</td></tr><?php else:foreach($topRows as $row):$start=ns_parse_date(ns_value($row,'SEMANA_DESDE'));$weekLabel=$start?ns_week_label($start):'';$payload=ns_report_row_payload(['Semana'=>$weekLabel,'Tipo'=>ns_value($row,'TIPO_INSTALACION'),'Instalación'=>ns_value($row,'INSTALACION'),'TAG'=>ns_value($row,'TAG'),'Descripción'=>ns_value($row,'DESCRIPCION'),'Total alarmas'=>(int)ns_value($row,'TOTAL_ALARMAS'),'Campo externo'=>ns_value($row,'CAMPO_EXT'),'Comentario'=>ns_value($row,'COMENTARIO')]); ?><tr><td class="nsCheckCell"><?php if($reportReady)echo ns_report_pick(ns_report_key('actor',[ns_value($row,'SEMANA_DESDE'),ns_value($row,'TIPO_INSTALACION'),ns_value($row,'INSTALACION'),ns_value($row,'TAG')]),'row','Mal actor · '.ns_value($row,'INSTALACION').' · '.ns_value($row,'TAG'),$payload); ?></td><td><?php echo h($weekLabel); ?></td><td><span class="nsType <?php echo h(ns_type_class(ns_value($row,'TIPO_INSTALACION'))); ?>"><?php echo h(ns_value($row,'TIPO_INSTALACION')); ?></span></td><td><b><?php echo h(ns_value($row,'INSTALACION')); ?></b></td><td><?php echo h(ns_value($row,'TAG')); ?></td><td><?php echo h(ns_value($row,'DESCRIPCION')); ?></td><td data-sort="<?php echo (int)ns_value($row,'TOTAL_ALARMAS'); ?>"><span class="nsTotal"><?php echo ns_num(ns_value($row,'TOTAL_ALARMAS')); ?></span></td><td><?php echo h(ns_value($row,'CAMPO_EXT')?:'—'); ?></td><td><?php echo ns_render_comment_button($row,$weekLabel,$canUseComments); ?></td></tr><?php endforeach;endif; ?></tbody></table></div></section>
<?php endif; ?></main></div><?php if($ready&&$canUseComments)ns_render_comment_modal(permissions_can('comments.create')); ?><?php if($ready): ?><script>window.CLEAR_WEEKLY_NEWS=<?php echo json_encode(['weeklyChart'=>$weeklyChart,'typeChart'=>$typeChart],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;</script><script src="assets/js/chart.umd.js"></script><?php endif; ?><script src="assets/js/app.js?v=20260826-ns3"></script><script src="assets/js/novedades_semanales.js?v=20260901-report-chart-2"></script></body></html>
